'use strict';
const $=id=>document.getElementById(id),c=$('scene'),g=c.getContext('2d');let data,playing=false,last=0;
function install(d){data=ReplayData.validate(d);playing=false;$('play').textContent='재생';$('time').min=d.traj[0].t;$('time').max=d.traj.at(-1).t;$('time').value=d.traj[0].t;const i=d.info;$('outcome').textContent=i?`${i.outcome} · 패드 오차 ${Number(i.miss).toFixed(2)} m · 손상 ${Number(i.damage).toFixed(3)}`:'최종 판정 기록 없음';draw();}
function draw(){if(!data)return;const s=ReplayData.sample(data,Number($('time').value)),a=data.traj,minX=Math.min(0,...a.map(v=>v.x))-30,maxX=Math.max(0,...a.map(v=>v.x))+30,maxZ=Math.max(...a.map(v=>v.z))+30,scale=Math.min(950/(maxX-minX),550/Math.max(1,maxZ));const pos=v=>({x:80+(v.x-minX)*scale,y:590-v.z*scale});g.clearRect(0,0,c.width,c.height);g.strokeStyle='#34506a';g.beginPath();g.moveTo(0,590);g.lineTo(1100,590);g.stroke();g.strokeStyle='#60cdb9';g.beginPath();a.forEach((v,i)=>{const p=pos(v);i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y);});g.stroke();const target=pos({x:0,z:0});g.fillStyle='#f6c377';g.fillRect(target.x-20*scale,588,40*scale,5);g.font='16px system-ui';g.fillText('패드 ±20 m',target.x-50,620);const p=pos(s);g.save();g.translate(p.x,p.y);g.rotate(s.th);g.fillStyle='#dbeaf4';g.fillRect(-6,-23,12,46);g.fillStyle='#ffb65a';if(s.u>0){g.beginPath();g.moveTo(-5,23);g.lineTo(0,23+s.u*35);g.lineTo(5,23);g.fill();}g.restore();g.fillStyle='#b8d0e2';g.fillText('고정 세계 좌표 · m · 저장된 궤적',24,30);$('stats').textContent=`t  ${s.t.toFixed(2)} s\nx  ${s.x.toFixed(2)} m\nz  ${s.z.toFixed(2)} m\nvx  ${s.vx.toFixed(2)} m/s\nvz  ${s.vz.toFixed(2)} m/s\n기울기  ${(s.th*180/Math.PI).toFixed(2)}°\n각속도  ${s.om.toFixed(4)} rad/s\n질량  ${s.m.toFixed(1)} kg\n출력 입력 u  ${s.u.toFixed(3)}\n손상 지표  ${s.D.toFixed(3)}`;}
$('play').onclick=()=>{if(!data)return;if(Number($('time').value)>=Number($('time').max))$('time').value=$('time').min;playing=!playing;$('play').textContent=playing?'일시정지':'재생';};
$('time').oninput=draw;$('start').onclick=()=>{if(data){$('time').value=$('time').min;draw();}};$('end').onclick=()=>{if(data){playing=false;$('play').textContent='재생';$('time').value=$('time').max;draw();}};
$('file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('10 MB 이하 파일을 선택하세요.');install(JSON.parse(await f.text()));$('error').textContent='';}catch(e){$('error').textContent=e.message;}};
function tick(t){if(playing&&data&&!document.hidden){$('time').value=Math.min(Number($('time').max),Number($('time').value)+Math.min(.1,(t-last)/1000));if(Number($('time').value)>=Number($('time').max)){playing=false;$('play').textContent='재생';}draw();}last=t;requestAnimationFrame(tick);}requestAnimationFrame(tick);
fetch('episode.json').then(r=>{if(!r.ok)throw Error('샘플 불러오기 실패');return r.json();}).then(install).catch(e=>$('error').textContent=e.message+' · 로컬 파일은 JSON 불러오기를 사용하세요.');
fetch('evaluations.json').then(r=>r.json()).then(d=>{for(const r of ReplayData.summarize(d)){const tr=document.createElement('tr');for(const v of [r.name,r.n,(r.success*100).toFixed(1)+'%',(r.pad*100).toFixed(1)+'%',r.contact,r.damage.toFixed(3)]){const td=document.createElement('td');td.textContent=v;tr.appendChild(td);}$('rows').appendChild(tr);}}).catch(e=>$('error').textContent=e.message);
